// Drives pi in RPC mode through a scenario: a long js call aborted mid-flight, then a settings change,
// then a status read; prints records and cua-repl process counts along the way.
//   node scenario-driver.mjs <pi-binary> <pi args...>
import { execFileSync, spawn } from "node:child_process";

const [piBinary, ...piArgs] = process.argv.slice(2);
const SLEEP_PROMPT =
    "Call the tool mcp__cua_repl__js twice. First call: code set to exactly: await cua.getState()\nSecond call: argument timeout_ms set to 90000 and code set to exactly: await new Promise((resolve) => setTimeout(resolve, 45000)); \"slept\"\nThen reply with one line. Do not call any other tool and do not control anything.";
const allSteps = [
    { id: "s1-sleep", prompt: SLEEP_PROMPT.replace("45000", process.env.SLEEP_MS ?? "45000"), abortAfterToolStartMs: 4000 },
    { id: "s2-browser-off", prompt: "/codex-computer-use browser off" },
    { id: "s3-status", prompt: "/codex-computer-use status" },
];
const steps = process.env.SCENARIO === "abort-only" ? [allSteps[0]] : allSteps;
const count = () => {
    try {
        return execFileSync("sh", ["-c", "pgrep -f cua-repl.mjs | wc -l"], { encoding: "utf8" }).trim();
    } catch {
        return "?";
    }
};
console.log(`cua-repl processes before pi: ${count()}`);
const child = spawn(piBinary, piArgs, { stdio: ["pipe", "pipe", "pipe"] });
child.stderr.on("data", (chunk) => {
    const text = chunk.toString();
    if (!text.startsWith("Warning: No models")) process.stdout.write(`[stderr] ${text}`);
});
const send = (record) => {
    console.log(`>>> ${JSON.stringify(record).slice(0, 200)}`);
    child.stdin.write(`${JSON.stringify(record)}\n`);
};
let stepIndex = -1;
let current;
let abortTimer;
const next = () => {
    stepIndex += 1;
    current = steps[stepIndex];
    if (!current) {
        const waitMs = Number(process.env.LINGER_MS ?? 1000);
        console.log(`cua-repl processes before shutdown: ${count()} (lingering ${waitMs} ms for turn_ended)`);
        setTimeout(() => child.kill("SIGTERM"), waitMs);
        return;
    }
    console.log(`\n##### ${current.id} (processes now: ${count()})`);
    send({ id: current.id, type: "prompt", message: current.prompt });
};
let buffer = "";
child.stdout.on("data", (chunk) => {
    buffer += chunk.toString();
    let nl = buffer.indexOf("\n");
    while (nl !== -1) {
        const line = buffer.slice(0, nl).trim();
        buffer = buffer.slice(nl + 1);
        nl = buffer.indexOf("\n");
        if (!line) continue;
        let record;
        try {
            record = JSON.parse(line);
        } catch {
            console.log(`<<< (raw) ${line.slice(0, 300)}`);
            continue;
        }
        if (record.type === "extension_ui_request") {
            console.log(`<<< ui ${record.method} ${JSON.stringify(record.message ?? record.statusText ?? "").slice(0, 400)}`);
            continue;
        }
        if (record.type === "response") {
            console.log(`<<< response ${JSON.stringify(record).slice(0, 250)}`);
            if (record.command === "prompt" && record.data?.disposition === "handled") setTimeout(next, 500);
            continue;
        }
        if (record.type === "tool_execution_start") {
            console.log(`<<< event tool_execution_start ${record.toolName} ${JSON.stringify(record.args ?? "").slice(0, 160)}`);
            const code = typeof record.args?.code === "string" ? record.args.code : "";
            if (current?.abortAfterToolStartMs && !abortTimer && code.includes("setTimeout")) {
                abortTimer = setTimeout(() => {
                    console.log(`(aborting; processes now: ${count()})`);
                    send({ type: "abort" });
                }, current.abortAfterToolStartMs);
            }
        } else if (record.type === "tool_execution_end") {
            console.log(`<<< event tool_execution_end ${record.toolName} isError=${record.isError} ${JSON.stringify(record.result?.content?.[0]?.text ?? "").slice(0, 200)}`);
        } else if (record.type === "agent_end") {
            console.log("<<< event agent_end");
            abortTimer = undefined;
            setTimeout(next, 1500);
        } else if (record.type === "agent_start" || record.type === "turn_end") {
            console.log(`<<< event ${record.type}`);
        }
    }
});
child.on("exit", (code, signal) => {
    console.log(`pi exited code=${code} signal=${signal}; cua-repl processes after exit: ${count()}`);
});
setTimeout(next, 1500);
setTimeout(() => {
    console.log("timeout: killing pi");
    child.kill("SIGKILL");
}, 300_000).unref();

// Drives pi in RPC mode: sends one prompt, aborts a few seconds after the first tool execution starts,
// prints the records, then exits once the agent settles. Usage:
//   node interrupt-driver.mjs <abortDelayMs> <pi-binary> <pi args...> -- <prompt>
import { spawn } from "node:child_process";

const argv = process.argv.slice(2);
const abortDelayMs = Number(argv[0]);
const separator = argv.indexOf("--");
const piArgs = argv.slice(1, separator);
const prompt = argv.slice(separator + 1).join(" ");
const [piBinary, ...rest] = piArgs;
const child = spawn(piBinary, rest, { stdio: ["pipe", "pipe", "pipe"] });
child.stderr.on("data", (chunk) => {
    const text = chunk.toString();
    if (!text.startsWith("Warning: No models")) process.stdout.write(`[stderr] ${text}`);
});
const send = (record) => {
    console.log(`>>> ${JSON.stringify(record)}`);
    child.stdin.write(`${JSON.stringify(record)}\n`);
};
let aborted = false;
let buffer = "";
const finish = () => {
    setTimeout(() => {
        child.kill("SIGTERM");
    }, 1500);
};
child.stdout.on("data", (chunk) => {
    buffer += chunk.toString();
    let nl = buffer.indexOf("\n");
    while (nl !== -1) {
        const line = buffer.slice(0, nl).trim();
        buffer = buffer.slice(nl + 1);
        nl = buffer.indexOf("\n");
        if (!line) continue;
        let record;
        try {
            record = JSON.parse(line);
        } catch {
            console.log(`<<< (raw) ${line.slice(0, 300)}`);
            continue;
        }
        if (record.type === "extension_ui_request") {
            console.log(`<<< ui ${record.method} ${JSON.stringify(record.message ?? record.statusText ?? "").slice(0, 300)}`);
            continue;
        }
        if (record.type === "response") {
            console.log(`<<< response ${JSON.stringify(record).slice(0, 300)}`);
            continue;
        }
        const summary =
            record.type === "tool_execution_start"
                ? `${record.toolName} ${JSON.stringify(record.args ?? "").slice(0, 200)}`
                : record.type === "tool_execution_end"
                  ? `${record.toolName} isError=${record.isError}`
                  : record.type === "agent_end" || record.type === "agent_settled" || record.type === "agent_start"
                    ? ""
                    : "";
        if (["tool_execution_start", "tool_execution_end", "agent_start", "agent_end", "agent_settled", "turn_end", "message_end"].includes(record.type))
            console.log(`<<< event ${record.type} ${summary}`);
        if (record.type === "tool_execution_start" && !aborted) {
            aborted = true;
            setTimeout(() => send({ type: "abort" }), abortDelayMs);
        }
        if (record.type === "agent_end") finish();
    }
});
child.on("exit", (code, signal) => console.log(`pi exited code=${code} signal=${signal}`));
setTimeout(() => send({ id: "p1", type: "prompt", message: prompt }), 1500);
setTimeout(() => {
    console.log("timeout: killing pi");
    child.kill("SIGKILL");
}, 180_000).unref();

// Calls js through the package's own connection (no model): getState, then a 150000-char string,
// then a 30000-char string; prints raw result sizes and the converted (truncated) model-facing content.
import { join } from "node:path";

const dist = process.argv[2];
const { discoverRuntime } = await import(join(dist, "runtime.js"));
const { openConnection } = await import(join(dist, "connection.js"));
const { buildCallMeta, convertCallToolResult, BYTES_PER_TOKEN } = await import(join(dist, "tools.js"));
const { BridgeLog } = await import(join(dist, "log.js"));

const log = new BridgeLog("/tmp/cua-03/direct-call.log");
const plan = await discoverRuntime();
if (plan.kind !== "plan") throw new Error(plan.message);
const connection = await openConnection({ plan, state: { computerUse: true, browserUse: true }, log });
const sessionId = "direct-call-session";
const turnId = `turn-${Date.now()}`;
const call = async (code, label) => {
    const started = Date.now();
    const result = await connection.client.request(
        "tools/call",
        { name: "js", arguments: { code, title: label }, _meta: buildCallMeta({ callId: `call_${label}`, sessionId, turnId, model: "probe" }) },
        { timeoutMs: 0 },
    );
    const converted = await convertCallToolResult(result, { tool: "js", limitBytes: plan.outputTokenLimit * BYTES_PER_TOKEN, durationMs: Date.now() - started });
    console.log(`\n### ${label}: isError=${result.isError ?? false} rawBlocks=${result.content.map((b) => `${b.type}:${b.text?.length ?? b.data?.length ?? 0}`).join(",")} resultMeta=${JSON.stringify(result._meta ?? null).slice(0, 200)}`);
    console.log(`converted blocks=${converted.content.map((b) => `${b.type}:${b.text?.length ?? b.data?.length ?? 0}`).join(",")} details=${JSON.stringify({ ...converted.details, resultMeta: undefined })}`);
    const text = converted.content.find((b) => b.type === "text")?.text ?? "";
    console.log(`first 160 chars: ${JSON.stringify(text.slice(0, 160))}`);
    console.log(`last 160 chars: ${JSON.stringify(text.slice(-160))}`);
    return result;
};
await call("await cua.getState()", "getState");
await call('"x".repeat(150000)', "repeat150k");
await call('"y".repeat(30000)', "repeat30k");
await call("nodeRepl.write(\"z\".repeat(120000)); \"done\"", "write120k");
await connection.client.request("tools/call", { name: "turn_ended", arguments: { hook_event_name: "Stop", session_id: sessionId, turn_id: turnId } }, { timeoutMs: 10_000 });
await connection.close();
console.log("\nclosed");

// Finds how large a bare expression value the REPL still echoes as the js result (no model).
import { join } from "node:path";
const dist = process.argv[2];
const { discoverRuntime } = await import(join(dist, "runtime.js"));
const { openConnection } = await import(join(dist, "connection.js"));
const { buildCallMeta } = await import(join(dist, "tools.js"));
const { BridgeLog } = await import(join(dist, "log.js"));
const log = new BridgeLog("/tmp/cua-03/echo-threshold.log");
const plan = await discoverRuntime();
if (plan.kind !== "plan") throw new Error(plan.message);
const connection = await openConnection({ plan, state: { computerUse: true, browserUse: false }, log });
const sessionId = "echo-threshold";
const turnId = `turn-${Date.now()}`;
const call = async (code) => {
    const result = await connection.client.request(
        "tools/call",
        { name: "js", arguments: { code }, _meta: buildCallMeta({ callId: `call_${Math.random().toString(36).slice(2)}`, sessionId, turnId, model: "probe" }) },
        { timeoutMs: 0 },
    );
    return result.content.map((b) => `${b.type}:${b.text?.length ?? 0}`).join(",") + (result.isError ? " (isError)" : "");
};
console.log("getState:", await call("await cua.getState()"));
for (const n of [100, 1000, 4000, 8000, 12000, 16000, 24000]) console.log(`"a".repeat(${n}):`, await call(`"a".repeat(${n})`));
console.log("object:", await call("({ a: 1, b: [1,2,3] })"));
console.log("number:", await call("1 + 1"));
console.log("undefined:", await call("let q = 1;"));
console.log("write 50k + value:", await call('nodeRepl.write("w".repeat(50000)); "v"'));
await connection.client.request("tools/call", { name: "turn_ended", arguments: { hook_event_name: "Stop", session_id: sessionId, turn_id: turnId } }, { timeoutMs: 30_000 });
await connection.close();
